/// <summary>
/// InventDim table extension
/// </summary>
[ExtensionOf(tableStr(InventDim))]
Public final class METInventDim_Extension
{
}

Method.Source:
    /// <summary>
    /// Return a dimension value for a given DimId and Field id
    /// </summary>
    /// <param name = "_inventDimId">Dim id</param>
    /// <param name = "_fieldNum">Field id</param>
    /// <returns>field value</returns>
    public static str metGetInventDimensionFromId(InventDimId _inventDimId, int _fieldNum)
    {
        Inventdim   inventDim; 
        str         ret;

        try
        {
            if(_inventDimId && _fieldNum)
            {
                select firstOnly inventDim
                    where   inventdim.inventDimId == _inventDimId;

                ret = inventdim.(_fieldNum);
            }
            else
            {
                ret = METConstants::emptyString;
            }
        }
        catch
        {
                ret = METConstants::emptyString;
        }
        
        return ret;
    }
